const $=id=>document.getElementById(id);
const drawer=$('chat-drawer');
function openChat(){drawer.hidden=false;$('message').focus();}
$('open-chat').onclick=openChat;$('close-chat').onclick=()=>drawer.hidden=true;
$('hud-keyboard').addEventListener('click',openChat);
$('rail-talk').onclick=$('quick-talk').onclick=()=>{$('voice-start').click();};
$('voice-start').addEventListener('click',()=>{drawer.hidden=false;});
$('manage-providers').onclick=()=>$('settings-button').click();
$('focus-mode').onclick=()=>document.body.classList.toggle('focused');
document.addEventListener('keydown',e=>{if(e.key==='Escape')drawer.hidden=true;});
for(const b of document.querySelectorAll('[data-prompt]'))b.addEventListener('click',openChat);
const detail=$('detail-dialog');$('close-detail').onclick=()=>detail.close();
async function get(path){const token=sessionStorage.getItem('jarvis.token');if(!token)throw new Error('Connect your workspace in Connection settings to view this panel.');const r=await fetch(path,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw new Error('Workspace data is unavailable. Check your connection.');return r.json();}
function rows(data){const value=data?.data??data;return Array.isArray(value)?value:value?.items||[];}
async function show(name,path){$('detail-title').textContent=name;$('detail-content').textContent='Loading…';detail.showModal();try{const items=rows(await get(path));$('detail-content').replaceChildren();if(!items.length)$('detail-content').textContent='Nothing here yet. Ask JARVIS to add something.';for(const item of items){const row=document.createElement('div');row.className='detail-row';row.textContent=item.title||item.content||item.message||item.name||'Saved item';$('detail-content').append(row);}}catch(e){$('detail-content').textContent=e.message;}}
for(const b of document.querySelectorAll('[data-nav]'))b.onclick=()=>{const key=b.dataset.nav;if(key==='chat'){openChat();return;}if(key==='tasks')return show('TASKS','/v1/tasks');if(key==='calendar')return show('REMINDERS','/v1/reminders');if(key==='memory')return show('MEMORY','/v1/memories');if(key==='knowledge')return show('NOTES','/v1/notes');if(key==='home'||key==='core'){drawer.hidden=true;document.querySelector('.hero').scrollIntoView({behavior:'smooth',block:'center'});return;}if(key==='agents'||key==='tools'){document.querySelector('.agents').scrollIntoView({behavior:'smooth',block:'center'});return;}$('detail-title').textContent='WORKFLOWS';$('detail-content').textContent='Ask JARVIS to help with tasks, notes and reminders. Autonomous multi-agent workflows are not configured.';detail.showModal();};
let lastToken='',lastRefresh=0;
async function refresh(){const token=sessionStorage.getItem('jarvis.token')||'';if(!token){lastToken='';$('top-status').textContent='● STANDBY';$('provider-groq').textContent=$('provider-fish').textContent='Not connected';return;}if(token===lastToken&&Date.now()-lastRefresh<30000)return;lastToken=token;lastRefresh=Date.now();try{const cap=await get('/v1/capabilities');$('provider-groq').textContent=cap.integrations.model.mock?'Demo mode':cap.integrations.model.status;$('provider-fish').textContent=cap.integrations.speech_synthesis.status;$('top-status').textContent='● CONNECTED';const results=await Promise.allSettled(['/v1/memories','/v1/notes','/v1/reminders','/v1/tasks'].map(get));for(let i=0;i<2;i++)if(results[i].status==='fulfilled')$(i?'note-count':'memory-count').textContent=rows(results[i].value).length;if(results[0].status==='fulfilled')$('memory-total').textContent=rows(results[0].value).length+' stored';if(results[2].status==='fulfilled'){const list=rows(results[2].value);$('timeline').replaceChildren();if(!list.length)$('timeline').textContent='No reminders scheduled.';for(const item of list.slice(0,3)){const el=document.createElement('div');el.className='timeline-entry';el.textContent='● '+(item.title||item.message||'Reminder');$('timeline').append(el);}}if(results[3].status==='fulfilled'){document.getElementById('task-feed-count')?.remove();const el=document.createElement('div');el.id='task-feed-count';el.className='feed-row';el.textContent=rows(results[3].value).length+' tasks in your workspace';$('intelligence-feed').prepend(el);}}catch{lastToken='';}}
setInterval(()=>{refresh();$('bottom-voice').textContent=$('hud-call-state').textContent;},2500);refresh();
